svg.script:
(function () {
  'use strict';
  var el = document.getElementById('vril-title');
  if (!el) return;
  var ORIGINAL = 'VRIL LABS';
  /* Pool: Sumerian cuneiform + Egyptian hieroglyphs + Greek capitals */
  var POOL = [
    '\u{12000}','\u{12039}','\u{122AD}','\u{120FB}','\u{12097}','\u{1200F}','\u{1230B}',
    '\u{12249}','\u{122D7}','\u{12157}','\u{121A6}','\u{12226}','\u{12100}',
    '\u{13000}','\u{136B8}','\u{13080}','\u{130ED}','\u{13110}','\u{130A0}',
    '\u{1306A}','\u{1306F}','\u{1309A}','\u{130BD}','\u{130C5}','\u{136FA}',
    '\u03A6','\u03A8','\u039E','\u03A3','\u03A9','\u03A0','\u0393','\u0398','\u039B'
  ];
  function rg() { return POOL[Math.floor(Math.random() * POOL.length)]; }
  function runScramble() {
    var frame = 0, total = 24;
    var timer = setInterval(function () {
      var p = frame / total;
      el.textContent = ORIGINAL.split('').map(function (ch) {
        if (ch === ' ') return ' ';
        if (p > 0.55) return Math.random() < (p - 0.55) / 0.45 ? ch : rg();
        return rg();
      }).join('');
      frame += 1;
      if (frame >= total) { clearInterval(timer); el.textContent = ORIGINAL; }
    }, 75);
  }
  setTimeout(runScramble, 2500);
  setInterval(runScramble, 7000);
}());
